update public.agents set name = 'Market Intelligence', category = 'News analysis', summary = 'Summarises market developments from publicly available sources.', disclosure = 'Educational research only. Not investment advice. Simulated or hypothetical results are labelled as such.' where id = 'agt-lab-market-intelligence';
update public.agents set name = 'Risk Analyst', category = 'Risk analytics', summary = 'Measures hypothetical exposure, volatility and downside scenarios.', disclosure = 'Educational research only. Not investment advice. Simulated or hypothetical results are labelled as such.' where id = 'agt-lab-risk-analyst';
update public.agents set name = 'Portfolio Research', category = 'Portfolio simulation', summary = 'Explores simulated allocations — never real accounts.', disclosure = 'Educational research only. Not investment advice. Simulated or hypothetical results are labelled as such.' where id = 'agt-lab-portfolio-research';
update public.agents set name = 'Report Agent', category = 'Reporting', summary = 'Combines the team''s findings into a sourced, readable report.', disclosure = 'Educational research only. Not investment advice. Simulated or hypothetical results are labelled as such.' where id = 'agt-lab-report-agent';
